const MODULE_ID = "cyberpunk-equipment-library";
const FLAVOR = {"Scarlet Mist":"<p data-cpel-flavor=\"substance-1\">Кровавый дождь выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — густой тёмно-красный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сладковато-химический запах с лёгкой нотой дыма, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Nettleweed Residue":"<p data-cpel-flavor=\"substance-1\">Жгучий контур выглядит как вязкий гель с полимерной основой; он медленно растекается по стеклу и после высыхания оставляет полупрозрачную матовую плёнку. Основной оттенок — жемчужно-серый; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества почти стерильный запах, за которым остаётся горький минеральный шлейф, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Контакт сопровождается резким жжением, которое быстро сменяется глубоким зудом и ощущением натянутой кожи. Поверхность становится чрезмерно чувствительной: ткань одежды, холодный воздух и даже собственное движение воспринимаются как раздражение. При сильном воздействии боль уходит глубже, превращаясь в тупое горячее давление в тканях. После спада остаётся болезненная чувствительность и ощущение сухости, будто кожа стала слишком тонкой для окружающего мира.</p>","Mindfog Mist":"<p data-cpel-flavor=\"substance-1\">Серый экран выглядит как сухой микрокристаллический порошок, который в герметичном стекле выглядит почти невесомым; отдельные частицы цепляются за стенки и образуют тонкий ореол. Основной оттенок — дымчато-серый; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества слабый металлический запах с аптечной горечью, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","False Hope":"<p data-cpel-flavor=\"substance-1\">Отложенный приговор выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — густой тёмно-красный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества запах холодного пластика, мяты и железа, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Bottled Catharsis (Moderate)":"<p data-cpel-flavor=\"substance-1\">Нейрококтейль «Катарсис» [Средний] хранится как двухфазный нейрококтейль: прозрачная основа и почти бесцветный, но с ярким неоновым отблеском взвесь не смешиваются полностью, а образуют медленные спирали. При лёгком движении флакона по стеклу пробегают жемчужные полосы, будто жидкость реагирует на ритм пульса. На вкус коктейль одновременно терпкий и сладковатый, после него на нёбе остаётся прохладная горечь; запах — запах холодного пластика, мяты и железа. Эта высококонцентрированная профессиональная формула, поэтому рисунок взвеси у неё гуще и держится дольше.</p><p data-cpel-flavor=\"substance-2\">Эффект начинается с неожиданно глубокого вдоха и ощущения, будто из груди сняли слишком тесный ремень. Навязчивые эмоции не исчезают, но перестают занимать всё внимание: страх, злость или эйфория отступают на фон, позволяя снова отделять собственные решения от химически усиленной реакции. Иногда это сопровождается короткой дрожью, слезами или приступом смеха — нервная система сбрасывает накопившееся напряжение прежде, чем возвращается к ровному состоянию.</p>","Hero Killer":"<p data-cpel-flavor=\"substance-1\">Антигерой выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — медно-янтарный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества слабый металлический запах с аптечной горечью, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Запах быстро перестаёт быть просто запахом и превращается в навязчивую точку внимания. Кажется, что источник находится совсем рядом и почему-то важен, хотя разум не может объяснить почему. Все остальные ощущения отходят на второй план, и даже движение невольно подстраивается под попытку приблизиться к знакомому аромату. Когда эффект ослабевает, остаётся неприятное понимание того, насколько естественным и собственным казалось это чужое желание.</p>","Black Smear Poison":"<p data-cpel-flavor=\"substance-1\">Сажа-9 выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — угольно-чёрный с масляным фиолетовым бликом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества почти стерильный запах, за которым остаётся горький минеральный шлейф, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Воздействие начинается с мелкой дрожи и ощущения неправильного веса конечностей. Пальцы перестают точно дозировать усилие, шаг становится слишком широким или коротким, а простые движения требуют сознательного контроля. По мере усиления эффекта мышцы будто получают команды с задержкой: тело ещё понимает, что нужно сделать, но ответ приходит поздно и рывками. После спада долго остаются покалывание и неприятная слабость, словно после сильного переохлаждения.</p>","Cave Worm Venom":"<p data-cpel-flavor=\"substance-1\">Глубинный стоп выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — бледно-зелёный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества слабый металлический запах с аптечной горечью, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Arsenic":"<p data-cpel-flavor=\"substance-1\">Белый шум выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — молочно-белый с холодным серым отливом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сладковато-химический запах с лёгкой нотой дыма, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые ощущения приходят изнутри: во рту появляется кислая горечь, желудок тяжелеет, а по спине проходит холодный пот. Затем к тошноте добавляются спазмы и ощущение, будто организм пытается избавиться от всего сразу. Движение и резкие запахи делают состояние хуже, поэтому человек инстинктивно старается замереть и дышать мелко. Даже после ослабления действия ещё некоторое время остаются слабость, сухость во рту и неприятная пустота в животе.</p>","Forensic Dye":"<p data-cpel-flavor=\"substance-1\">Криминалистический реагент «Синий след» выглядит как абсолютно прозрачный реагент, в котором заметны только редкие синие микрогранулы. В покое они оседают тонким кольцом, а после движения раствор снова становится оптически чистым. Запах почти отсутствует, лишь у самого горлышка чувствуется слабая минеральная нота и озон. На поверхности высохший состав образует бесцветную матовую плёнку, поэтому характерная синяя окраска воспринимается особенно резко, когда реагент действительно вступает в нужную реакцию.</p><p data-cpel-flavor=\"substance-2\">Сам по себе реагент почти не меняется, и именно поэтому его реакция выглядит столь выразительно. При совпадении с нужным материалом бесцветная плёнка за секунды набирает чистый электрически-синий тон, словно под поверхностью включили подсветку. Цвет идёт не пятнами, а тонкими ветвящимися линиями и постепенно сливается в сплошную метку; при отсутствии совпадения поверхность остаётся тусклой и практически бесцветной.</p>","Graveroot":"<p data-cpel-flavor=\"substance-1\">Холодный узел выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — прозрачный с опаловым переливом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества слабый металлический запах с аптечной горечью, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Deathcap Powder":"<p data-cpel-flavor=\"substance-1\">Серый урожай выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — дымчато-серый; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества резкий травяной запах с перечной нотой, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые ощущения приходят изнутри: во рту появляется кислая горечь, желудок тяжелеет, а по спине проходит холодный пот. Затем к тошноте добавляются спазмы и ощущение, будто организм пытается избавиться от всего сразу. Движение и резкие запахи делают состояние хуже, поэтому человек инстинктивно старается замереть и дышать мелко. Даже после ослабления действия ещё некоторое время остаются слабость, сухость во рту и неприятная пустота в животе.</p>","King's Sleep":"<p data-cpel-flavor=\"substance-1\">Долгий ноль выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — медно-янтарный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сладковато-химический запах с лёгкой нотой дыма, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Medpatch (Ultimate)":"<p data-cpel-flavor=\"substance-1\">Медпластырь [Абсолютный] выглядит как тонкая гибкая пластина из матового биополимера с едва заметной сеткой микрорезервуаров. У этой версии сетка плотнее, чем у младших моделей, а клеевой слой холодит кожу уже при соприкосновении. Внутри пластыря просматривается жемчужно-серый гель; от вскрытой защитной мембраны остаётся сладковато-химический запах с лёгкой нотой дыма. Это предельная по концентрации версия, визуально почти не похожая на бытовые аналоги, поэтому сам пластырь ощущается чуть тяжелее и жёстче обычного медицинского расходника.</p><p data-cpel-flavor=\"substance-2\">После фиксации сначала чувствуется холод клеевого слоя, затем под кожей появляется мягкое покалывание и ритмичное тепло вокруг травмированных участков. Боль не исчезает мгновенно, но становится тише и «дальше», дыхание выравнивается, а напряжённые мышцы постепенно отпускают. По мере расходования микрорезервуаров сетка внутри пластыря тускнеет; к концу работы остаётся только равномерное тепло и лёгкая стянутость кожи.</p>","False Death":"<p data-cpel-flavor=\"substance-1\">Нулевая линия выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — бледно-зелёный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества слабый металлический запах с аптечной горечью, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Воздействие начинается с мелкой дрожи и ощущения неправильного веса конечностей. Пальцы перестают точно дозировать усилие, шаг становится слишком широким или коротким, а простые движения требуют сознательного контроля. По мере усиления эффекта мышцы будто получают команды с задержкой: тело ещё понимает, что нужно сделать, но ответ приходит поздно и рывками. После спада долго остаются покалывание и неприятная слабость, словно после сильного переохлаждения.</p>","Spider Root":"<p data-cpel-flavor=\"substance-1\">Узел-6 выглядит как вязкий гель с полимерной основой; он медленно растекается по стеклу и после высыхания оставляет полупрозрачную матовую плёнку. Основной оттенок — дымчато-синий; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества кисловатый запах электролита и мокрого камня, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Воздействие начинается с мелкой дрожи и ощущения неправильного веса конечностей. Пальцы перестают точно дозировать усилие, шаг становится слишком широким или коротким, а простые движения требуют сознательного контроля. По мере усиления эффекта мышцы будто получают команды с задержкой: тело ещё понимает, что нужно сделать, но ответ приходит поздно и рывками. После спада долго остаются покалывание и неприятная слабость, словно после сильного переохлаждения.</p>","Violet Venom":"<p data-cpel-flavor=\"substance-1\">Пурпурный сбой выглядит как вязкий гель с полимерной основой; он медленно растекается по стеклу и после высыхания оставляет полупрозрачную матовую плёнку. Основной оттенок — фиолетовый с синеватой иризацией; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества кисловатый запах электролита и мокрого камня, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Curare":"<p data-cpel-flavor=\"substance-1\">Стоп-кадр выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — прозрачный с опаловым переливом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сухой запах озона и горьких трав, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Воздействие начинается с мелкой дрожи и ощущения неправильного веса конечностей. Пальцы перестают точно дозировать усилие, шаг становится слишком широким или коротким, а простые движения требуют сознательного контроля. По мере усиления эффекта мышцы будто получают команды с задержкой: тело ещё понимает, что нужно сделать, но ответ приходит поздно и рывками. После спада долго остаются покалывание и неприятная слабость, словно после сильного переохлаждения.</p>","Blood Sap":"<p data-cpel-flavor=\"substance-1\">Красный разгон / Red Rush — густой тёмно-красный сироп с почти чёрным отливом. В ампуле он движется медленно, как тяжёлое масло, и оставляет на стекле тонкую красную плёнку. Запах напоминает железо, вишнёвый сироп и озон; вкус приторно-сладкий, но быстро сменяется металлической горечью. При комнатной температуре в жидкости видны тонкие яркие нити, которые исчезают, если согреть ампулу в ладони.</p><p data-cpel-flavor=\"substance-2\">Первое ощущение — сильное тепло в груди и плечах, затем пульс становится отчётливо слышен в ушах. Мышцы кажутся легче и отзывчивее, движения получают неприятную пружинящую резкость, будто тело заранее готово сорваться в рывок. За этим приходит обратная сторона: дыхание становится грубее, во рту появляется вкус железа, а после окончания разгона конечности ощущаются тяжёлыми и опустошёнными.</p>","Numbing Tonic (Greater)":"<p data-cpel-flavor=\"substance-1\">Нейроанальгетик «Онемение» [Сильный] — вязкий нейроанальгетический тоник с гладкой, почти сиропной текстурой. Жидкость почти бесцветный, но с ярким неоновым отблеском, медленно собирается на стенках ампулы и при встряхивании даёт тонкое опаловое кольцо. Во вкусе сначала ощущается холодная сладость, затем появляется аптечная горечь и характерное онемение языка; запах — резкий травяной запах с перечной нотой. По плотности это тяжёлая формула с заметно более насыщенным носителем, и старшие версии заметно дольше сохраняют ощущение прохлады во рту.</p><p data-cpel-flavor=\"substance-2\">Онемение начинается с губ и языка, затем волной спускается по шее и плечам. Боль не пропадает как выключенный сигнал — скорее становится приглушённой и далёкой, позволяя телу продолжать работу, несмотря на повреждения. На пике движения ощущаются чуть «чужими», потому что обратная связь от мышц приходит слабее обычного; после спада чувствительность возвращается покалыванием, теплом и тяжестью в уставших конечностях.</p>","Bottled Catharsis (Major)":"<p data-cpel-flavor=\"substance-1\">Нейрококтейль «Катарсис» [Высший] хранится как двухфазный нейрококтейль: прозрачная основа и почти бесцветный, но с ярким неоновым отблеском взвесь не смешиваются полностью, а образуют медленные спирали. При лёгком движении флакона по стеклу пробегают жемчужные полосы, будто жидкость реагирует на ритм пульса. На вкус коктейль одновременно терпкий и сладковатый, после него на нёбе остаётся прохладная горечь; запах — почти стерильный запах, за которым остаётся горький минеральный шлейф. Эта предельная по концентрации версия, визуально почти не похожая на бытовые аналоги, поэтому рисунок взвеси у неё гуще и держится дольше.</p><p data-cpel-flavor=\"substance-2\">Эффект начинается с неожиданно глубокого вдоха и ощущения, будто из груди сняли слишком тесный ремень. Навязчивые эмоции не исчезают, но перестают занимать всё внимание: страх, злость или эйфория отступают на фон, позволяя снова отделять собственные решения от химически усиленной реакции. Иногда это сопровождается короткой дрожью, слезами или приступом смеха — нервная система сбрасывает накопившееся напряжение прежде, чем возвращается к ровному состоянию.</p>","Poison Fizz (Greater)":"<p data-cpel-flavor=\"substance-1\">Антитокс-леденец «Шипучка» [Сильный] выполнен в форме плотного шипучего леденца с полупрозрачной оболочкой и зернистой сердцевиной. Оболочка жемчужно-серый; внутри видны крошечные пузырьки, будто конфета всё время медленно «кипит». Во рту сначала чувствуется цитрусовая кислота, затем сильная лекарственная горечь и холод; запах — сладковато-химический запах с лёгкой нотой дыма. Эта тяжёлая формула с заметно более насыщенным носителем: чем выше грейд, тем плотнее сердцевина и тем ярче короткая вспышка цвета при раскусывании.</p><p data-cpel-flavor=\"substance-2\">Пока леденец растворяется, язык покалывает от кислоты и холода, а в горле остаётся слабое ощущение мятной сухости. Через несколько минут тело становится менее чувствительным к характерной токсической слабости: тошнота и дрожь не исчезают полностью, но воспринимаются контролируемее. Если задействуется вторичная капсула, сладкий вкус мгновенно сменяется сильной химической горечью и коротким ощущением жжения в носоглотке.</p>","Mustard Powder":"<p data-cpel-flavor=\"substance-1\">Жёлтая завеса выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — янтарно-жёлтый; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества почти стерильный запах, за которым остаётся горький минеральный шлейф, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Blisterwort":"<p data-cpel-flavor=\"substance-1\">Стеклокожа выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — прозрачный с опаловым переливом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества запах холодного пластика, мяты и железа, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Контакт сопровождается резким жжением, которое быстро сменяется глубоким зудом и ощущением натянутой кожи. Поверхность становится чрезмерно чувствительной: ткань одежды, холодный воздух и даже собственное движение воспринимаются как раздражение. При сильном воздействии боль уходит глубже, превращаясь в тупое горячее давление в тканях. После спада остаётся болезненная чувствительность и ощущение сухости, будто кожа стала слишком тонкой для окружающего мира.</p>","Spider Venom":"<p data-cpel-flavor=\"substance-1\">Дёрганый кадр выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — винно-бордовый; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества резкий травяной запах с перечной нотой, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Воздействие начинается с мелкой дрожи и ощущения неправильного веса конечностей. Пальцы перестают точно дозировать усилие, шаг становится слишком широким или коротким, а простые движения требуют сознательного контроля. По мере усиления эффекта мышцы будто получают команды с задержкой: тело ещё понимает, что нужно сделать, но ответ приходит поздно и рывками. После спада долго остаются покалывание и неприятная слабость, словно после сильного переохлаждения.</p>","Forgetful Drops":"<p data-cpel-flavor=\"substance-1\">Чистый сектор выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — дымчато-синий; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сладковато-химический запах с лёгкой нотой дыма, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Numbing Tonic (True)":"<p data-cpel-flavor=\"substance-1\">Нейроанальгетик «Онемение» [Предельный] — вязкий нейроанальгетический тоник с гладкой, почти сиропной текстурой. Жидкость почти бесцветный, но с ярким неоновым отблеском, медленно собирается на стенках ампулы и при встряхивании даёт тонкое опаловое кольцо. Во вкусе сначала ощущается холодная сладость, затем появляется аптечная горечь и характерное онемение языка; запах — запах холодного пластика, мяты и железа. По плотности это предельная по концентрации версия, визуально почти не похожая на бытовые аналоги, и старшие версии заметно дольше сохраняют ощущение прохлады во рту.</p><p data-cpel-flavor=\"substance-2\">Онемение начинается с губ и языка, затем волной спускается по шее и плечам. Боль не пропадает как выключенный сигнал — скорее становится приглушённой и далёкой, позволяя телу продолжать работу, несмотря на повреждения. На пике движения ощущаются чуть «чужими», потому что обратная связь от мышц приходит слабее обычного; после спада чувствительность возвращается покалыванием, теплом и тяжестью в уставших конечностях.</p>","Pucker Pickle":"<p data-cpel-flavor=\"substance-1\">Кислый сторож / Sour Guard выглядит почти комично: маленький тёмно-зелёный маринованный плод с блестящей кожицей и ярко-жёлтой сердцевиной. Рассол густой, пряный и пахнет уксусом, перцем и чем-то химически мятным; вкус сначала просто кислый, а через секунду становится настолько резким, что сводит челюсть. После укуса на языке остаётся солёное жжение, а от кожи ещё долго идёт отчётливый аромат специй и ферментированного биогеля.</p><p data-cpel-flavor=\"substance-2\">Эффект невозможно не заметить: кислота и специи обжигают язык, глаза на секунду слезятся, а потом во рту остаётся стойкий солёно-перечный привкус. Через несколько минут запах проступает уже через кожу и дыхание, превращаясь в неприятную смесь рассола, уксуса и резких ароматических соединений. Сам носитель почти не ощущает этого после первых минут, зато для любого существа с чувствительным вкусом или запахом он становится крайне непривлекательным.</p>","Creeping Death":"<p data-cpel-flavor=\"substance-1\">Медленный разряд выглядит как вязкий гель с полимерной основой; он медленно растекается по стеклу и после высыхания оставляет полупрозрачную матовую плёнку. Основной оттенок — жемчужно-серый; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества почти стерильный запах, за которым остаётся горький минеральный шлейф, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Smother Shroud":"<p data-cpel-flavor=\"substance-1\">Глухой купол выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — дымчато-синий; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества почти стерильный запах, за которым остаётся горький минеральный шлейф, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Knockout Dram":"<p data-cpel-flavor=\"substance-1\">Чёрный экран выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — угольно-чёрный с масляным фиолетовым бликом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества слабый металлический запах с аптечной горечью, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Сначала глохнут фоновые звуки и становится трудно удерживать взгляд на мелких деталях. Веки тяжелеют, мысли растягиваются, а короткие паузы между движениями неожиданно превращаются в несколько секунд неподвижности. Сонливость ощущается не уютной, а искусственно тяжёлой: тело словно получает приказ выключиться раньше, чем сознание готово уступить. При глубоком воздействии окружающее запоминается отдельными кадрами, разделёнными провалами.</p>","Forgetful Ink":"<p data-cpel-flavor=\"substance-1\">Слепая подпись выглядит как вязкий гель с полимерной основой; он медленно растекается по стеклу и после высыхания оставляет полупрозрачную матовую плёнку. Основной оттенок — бледно-зелёный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества запах холодного пластика, мяты и железа, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Taster's Folly":"<p data-cpel-flavor=\"substance-1\">Последний тост выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — бледно-зелёный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сухой запах озона и горьких трав, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые ощущения приходят изнутри: во рту появляется кислая горечь, желудок тяжелеет, а по спине проходит холодный пот. Затем к тошноте добавляются спазмы и ощущение, будто организм пытается избавиться от всего сразу. Движение и резкие запахи делают состояние хуже, поэтому человек инстинктивно старается замереть и дышать мелко. Даже после ослабления действия ещё некоторое время остаются слабость, сухость во рту и неприятная пустота в животе.</p>","Soothing Tonic (Major)":"<p data-cpel-flavor=\"substance-1\">Реген-тоник «Успокоение» [Высший] представляет собой прозрачный регенеративный тоник, в котором под светом видны тончайшие волокна биогеля. Основа дымчато-серый; при движении флакона волокна складываются в медленные завитки, словно жидкость пытается стянуть сама себя. Вкус мягкий, солоновато-травяной, с коротким металлическим послевкусием, а запах напоминает кисловатый запах электролита и мокрого камня. Эта тяжёлая формула с заметно более насыщенным носителем визуально отличается прежде всего плотностью волокон и более яркой реакцией на тепло ладони.</p><p data-cpel-flavor=\"substance-2\">В первые секунды по телу проходит мягкое тепло, особенно заметное вокруг свежих ран и перенапряжённых мышц. Кожа вокруг повреждений слегка зудит, затем чувство натяжения ослабевает, а мелкая дрожь после стресса постепенно уходит. Препарат не создаёт эйфории: его действие ощущается как спокойная физиологическая «сборка» организма, когда пульс выравнивается, дыхание становится глубже, а тело снова начинает слушаться без лишнего напряжения.</p>","Terror Spores":"<p data-cpel-flavor=\"substance-1\">Паник-пыль выглядит как сухой микрокристаллический порошок, который в герметичном стекле выглядит почти невесомым; отдельные частицы цепляются за стенки и образуют тонкий ореол. Основной оттенок — бледно-зелёный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества слабый металлический запах с аптечной горечью, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Восприятие начинает ошибаться раньше, чем человек понимает, что отравлен. Тени кажутся глубже, движения на краю зрения — слишком быстрыми, а обычные звуки получают тревожный второй слой. Организм реагирует на эти ложные сигналы вполне реально: учащается дыхание, ладони холодеют, мышцы готовятся к бегству. При тяжёлом воздействии граница между настоящей угрозой и химически созданным образом почти исчезает, оставляя после себя изматывающую настороженность.</p>","Unending Itch":"<p data-cpel-flavor=\"substance-1\">Дермакраш выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — молочно-белый с холодным серым отливом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сладковато-химический запах с лёгкой нотой дыма, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Brightshade":"<p data-cpel-flavor=\"substance-1\">Люмен-13 выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — почти бесцветный, но с ярким неоновым отблеском; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества резкий травяной запах с перечной нотой, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Контакт сопровождается резким жжением, которое быстро сменяется глубоким зудом и ощущением натянутой кожи. Поверхность становится чрезмерно чувствительной: ткань одежды, холодный воздух и даже собственное движение воспринимаются как раздражение. При сильном воздействии боль уходит глубже, превращаясь в тупое горячее давление в тканях. После спада остаётся болезненная чувствительность и ощущение сухости, будто кожа стала слишком тонкой для окружающего мира.</p>","Nethershade":"<p data-cpel-flavor=\"substance-1\">Тёмный пиксель выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — угольно-чёрный с масляным фиолетовым бликом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества слабый металлический запах с аптечной горечью, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Контакт сопровождается резким жжением, которое быстро сменяется глубоким зудом и ощущением натянутой кожи. Поверхность становится чрезмерно чувствительной: ткань одежды, холодный воздух и даже собственное движение воспринимаются как раздражение. При сильном воздействии боль уходит глубже, превращаясь в тупое горячее давление в тканях. После спада остаётся болезненная чувствительность и ощущение сухости, будто кожа стала слишком тонкой для окружающего мира.</p>","Ghost Ink":"<p data-cpel-flavor=\"substance-1\">Стелс-чернила «Призрак» — густые дымчато-серые чернила с холодным металлическим блеском. На стекле они кажутся почти чёрными, но тонкий слой быстро теряет насыщенность и становится визуально «пустым», оставляя лишь слабый графитовый перелив под косым светом. Чернила пахнут пластиком, озоном и сухой бумагой; по консистенции напоминают жидкий полимер и тянутся короткой нитью, прежде чем капля отделится от наконечника.</p><p data-cpel-flavor=\"substance-2\">Свежий штрих первое мгновение выглядит обычным тёмным следом, затем сереет, истончается и будто проваливается в материал. Под прямым светом поверхность кажется чистой, но под подходящим углом остаётся едва заметная разница фактуры, похожая на отпечаток от высохшей воды. Когда чернила проявляются штатным способом, линии возвращаются сразу целиком: резкие, холодно-серые и без привычного растекания по краям.</p>","Abysium Powder":"<p data-cpel-flavor=\"substance-1\">Чёрный кварц выглядит как вязкий гель с полимерной основой; он медленно растекается по стеклу и после высыхания оставляет полупрозрачную матовую плёнку. Основной оттенок — угольно-чёрный с масляным фиолетовым бликом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества почти стерильный запах, за которым остаётся горький минеральный шлейф, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые ощущения приходят изнутри: во рту появляется кислая горечь, желудок тяжелеет, а по спине проходит холодный пот. Затем к тошноте добавляются спазмы и ощущение, будто организм пытается избавиться от всего сразу. Движение и резкие запахи делают состояние хуже, поэтому человек инстинктивно старается замереть и дышать мелко. Даже после ослабления действия ещё некоторое время остаются слабость, сухость во рту и неприятная пустота в животе.</p>","Numbing Tonic (Minor)":"<p data-cpel-flavor=\"substance-1\">Нейроанальгетик «Онемение» [Малый] — вязкий нейроанальгетический тоник с гладкой, почти сиропной текстурой. Жидкость почти бесцветный, но с ярким неоновым отблеском, медленно собирается на стенках ампулы и при встряхивании даёт тонкое опаловое кольцо. Во вкусе сначала ощущается холодная сладость, затем появляется аптечная горечь и характерное онемение языка; запах — запах холодного пластика, мяты и железа. По плотности это мягкая по концентрации версия, и старшие версии заметно дольше сохраняют ощущение прохлады во рту.</p><p data-cpel-flavor=\"substance-2\">Онемение начинается с губ и языка, затем волной спускается по шее и плечам. Боль не пропадает как выключенный сигнал — скорее становится приглушённой и далёкой, позволяя телу продолжать работу, несмотря на повреждения. На пике движения ощущаются чуть «чужими», потому что обратная связь от мышц приходит слабее обычного; после спада чувствительность возвращается покалыванием, теплом и тяжестью в уставших конечностях.</p>","Elixir of Gender Transformation (Greater)":"<p data-cpel-flavor=\"substance-1\">Гендер-морф терапия [Сильный] выглядит как стерильная полупрозрачная эмульсия с россыпью микрокапсул, которые мерцают при повороте флакона. Основа прозрачный с опаловым переливом, без осадка и резких слоёв; при нагреве в ладони она становится чуть более текучей. Вкус нейтральный, с едва заметной минеральной сладостью, запах — резкий травяной запах с перечной нотой. Это плотная рабочая формула: у старших вариантов капсулы мельче, а сама эмульсия кажется почти однородной, словно свет рассеивается уже внутри жидкости.</p><p data-cpel-flavor=\"substance-2\">После приёма по телу расходится равномерное тепло и мелкое покалывание, особенно заметное в коже и мышцах. Проприоцепция начинает постепенно перестраиваться: знакомые движения на короткое время ощущаются непривычно, голос и дыхание воспринимаются иначе, а отражение меняется быстрее, чем мозг успевает к нему привыкнуть. Сам процесс не похож на резкий скачок — это последовательная биоморфная перенастройка, сопровождаемая усталостью и сильной жаждой.</p>","Scour":"<p data-cpel-flavor=\"substance-1\">Острый край / Razor Edge — прозрачная серебристая суспензия с тонкими игольчатыми кристаллами, которые вспыхивают на свету и тут же растворяются. Запах резкий, лимонно-озоновый, вкус сухой и колющий, словно язык коснулся батарейки. На стенках капсулы жидкость не образует обычных капель, а собирается в узкие дорожки, поэтому препарат выглядит подчеркнуто «острым» даже до того, как начинает действовать.</p><p data-cpel-flavor=\"substance-2\">Сначала обостряются мелочи: шорох ткани, холод металла, движение в периферии зрения. Реакции кажутся быстрыми и точными, пальцы сами находят привычные движения, а тело становится почти невесомым. Но усиленная чувствительность быстро превращается в перегрузку — яркий свет режет глаза, мышцы подрагивают, мысли перескакивают слишком быстро, и расслабиться становится почти невозможно.</p>","Poison Fizz (Lesser)":"<p data-cpel-flavor=\"substance-1\">Антитокс-леденец «Шипучка» [Слабый] выполнен в форме плотного шипучего леденца с полупрозрачной оболочкой и зернистой сердцевиной. Оболочка дымчато-синий; внутри видны крошечные пузырьки, будто конфета всё время медленно «кипит». Во рту сначала чувствуется цитрусовая кислота, затем сильная лекарственная горечь и холод; запах — кисловатый запах электролита и мокрого камня. Эта высококонцентрированная профессиональная формула: чем выше грейд, тем плотнее сердцевина и тем ярче короткая вспышка цвета при раскусывании.</p><p data-cpel-flavor=\"substance-2\">Пока леденец растворяется, язык покалывает от кислоты и холода, а в горле остаётся слабое ощущение мятной сухости. Через несколько минут тело становится менее чувствительным к характерной токсической слабости: тошнота и дрожь не исчезают полностью, но воспринимаются контролируемее. Если задействуется вторичная капсула, сладкий вкус мгновенно сменяется сильной химической горечью и коротким ощущением жжения в носоглотке.</p>","Zerk":"<p data-cpel-flavor=\"substance-1\">Овердрайв / Overdrive — густая красно-чёрная суспензия в коротком автоинъекторе. Жидкость разделяется на две фазы только после долгого покоя, а при движении мгновенно становится однородной и почти непрозрачной. Запах острый, железистый, с перцем и синтетическим каучуком. Через прозрачное окно инъектора состав выглядит так, будто в нём плавают тёмные искры; это не свечение, а металлические микрочастицы носителя.</p><p data-cpel-flavor=\"substance-2\">Действие приходит почти сразу резким ударом пульса. Слух выхватывает шаги и щелчки, мышцы напрягаются сами, а любое промедление ощущается как физически невыносимая задержка. Мир сужается до ближайшей задачи и возможной угрозы; в теле появляется ощущение лишней силы, но вместе с ним — дрожь, горячее дыхание и опасная склонность продолжать движение даже тогда, когда разум уже советует остановиться.</p>","Elixir of Gender Transformation (Lesser)":"<p data-cpel-flavor=\"substance-1\">Гендер-морф терапия [Слабый] выглядит как стерильная полупрозрачная эмульсия с россыпью микрокапсул, которые мерцают при повороте флакона. Основа винно-бордовый, без осадка и резких слоёв; при нагреве в ладони она становится чуть более текучей. Вкус нейтральный, с едва заметной минеральной сладостью, запах — сладковато-химический запах с лёгкой нотой дыма. Это мягкая по концентрации версия: у старших вариантов капсулы мельче, а сама эмульсия кажется почти однородной, словно свет рассеивается уже внутри жидкости.</p><p data-cpel-flavor=\"substance-2\">После приёма по телу расходится равномерное тепло и мелкое покалывание, особенно заметное в коже и мышцах. Проприоцепция начинает постепенно перестраиваться: знакомые движения на короткое время ощущаются непривычно, голос и дыхание воспринимаются иначе, а отражение меняется быстрее, чем мозг успевает к нему привыкнуть. Сам процесс не похож на резкий скачок — это последовательная биоморфная перенастройка, сопровождаемая усталостью и сильной жаждой.</p>","Elixir of Gender Transformation (Moderate)":"<p data-cpel-flavor=\"substance-1\">Гендер-морф терапия [Средний] выглядит как стерильная полупрозрачная эмульсия с россыпью микрокапсул, которые мерцают при повороте флакона. Основа медно-янтарный, без осадка и резких слоёв; при нагреве в ладони она становится чуть более текучей. Вкус нейтральный, с едва заметной минеральной сладостью, запах — сладковато-химический запах с лёгкой нотой дыма. Это плотная рабочая формула: у старших вариантов капсулы мельче, а сама эмульсия кажется почти однородной, словно свет рассеивается уже внутри жидкости.</p><p data-cpel-flavor=\"substance-2\">После приёма по телу расходится равномерное тепло и мелкое покалывание, особенно заметное в коже и мышцах. Проприоцепция начинает постепенно перестраиваться: знакомые движения на короткое время ощущаются непривычно, голос и дыхание воспринимаются иначе, а отражение меняется быстрее, чем мозг успевает к нему привыкнуть. Сам процесс не похож на резкий скачок — это последовательная биоморфная перенастройка, сопровождаемая усталостью и сильной жаждой.</p>","Medpatch (Advanced)":"<p data-cpel-flavor=\"substance-1\">Медпластырь [Продвинутый] выглядит как тонкая гибкая пластина из матового биополимера с едва заметной сеткой микрорезервуаров. У этой версии сетка плотнее, чем у младших моделей, а клеевой слой холодит кожу уже при соприкосновении. Внутри пластыря просматривается дымчато-синий гель; от вскрытой защитной мембраны остаётся слабый металлический запах с аптечной горечью. Это высококонцентрированная профессиональная формула, поэтому сам пластырь ощущается чуть тяжелее и жёстче обычного медицинского расходника.</p><p data-cpel-flavor=\"substance-2\">После фиксации сначала чувствуется холод клеевого слоя, затем под кожей появляется мягкое покалывание и ритмичное тепло вокруг травмированных участков. Боль не исчезает мгновенно, но становится тише и «дальше», дыхание выравнивается, а напряжённые мышцы постепенно отпускают. По мере расходования микрорезервуаров сетка внутри пластыря тускнеет; к концу работы остаётся только равномерное тепло и лёгкая стянутость кожи.</p>","Slumber Wine":"<p data-cpel-flavor=\"substance-1\">Тихий бокал выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — винно-бордовый; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества запах холодного пластика, мяты и железа, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Сначала глохнут фоновые звуки и становится трудно удерживать взгляд на мелких деталях. Веки тяжелеют, мысли растягиваются, а короткие паузы между движениями неожиданно превращаются в несколько секунд неподвижности. Сонливость ощущается не уютной, а искусственно тяжёлой: тело словно получает приказ выключиться раньше, чем сознание готово уступить. При глубоком воздействии окружающее запоминается отдельными кадрами, разделёнными провалами.</p>","Giant Wasp Venom":"<p data-cpel-flavor=\"substance-1\">Жёлтый шок выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — янтарно-жёлтый; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества запах холодного пластика, мяты и железа, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Воздействие начинается с мелкой дрожи и ощущения неправильного веса конечностей. Пальцы перестают точно дозировать усилие, шаг становится слишком широким или коротким, а простые движения требуют сознательного контроля. По мере усиления эффекта мышцы будто получают команды с задержкой: тело ещё понимает, что нужно сделать, но ответ приходит поздно и рывками. После спада долго остаются покалывание и неприятная слабость, словно после сильного переохлаждения.</p>","Soothing Tonic (Greater)":"<p data-cpel-flavor=\"substance-1\">Реген-тоник «Успокоение» [Сильный] представляет собой прозрачный регенеративный тоник, в котором под светом видны тончайшие волокна биогеля. Основа дымчато-серый; при движении флакона волокна складываются в медленные завитки, словно жидкость пытается стянуть сама себя. Вкус мягкий, солоновато-травяной, с коротким металлическим послевкусием, а запах напоминает запах холодного пластика, мяты и железа. Эта высококонцентрированная профессиональная формула визуально отличается прежде всего плотностью волокон и более яркой реакцией на тепло ладони.</p><p data-cpel-flavor=\"substance-2\">В первые секунды по телу проходит мягкое тепло, особенно заметное вокруг свежих ран и перенапряжённых мышц. Кожа вокруг повреждений слегка зудит, затем чувство натяжения ослабевает, а мелкая дрожь после стресса постепенно уходит. Препарат не создаёт эйфории: его действие ощущается как спокойная физиологическая «сборка» организма, когда пульс выравнивается, дыхание становится глубже, а тело снова начинает слушаться без лишнего напряжения.</p>","Toad Tears":"<p data-cpel-flavor=\"substance-1\">Болотный импульс выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — тёмно-зелёный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества запах холодного пластика, мяты и железа, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Запах быстро перестаёт быть просто запахом и превращается в навязчивую точку внимания. Кажется, что источник находится совсем рядом и почему-то важен, хотя разум не может объяснить почему. Все остальные ощущения отходят на второй план, и даже движение невольно подстраивается под попытку приблизиться к знакомому аромату. Когда эффект ослабевает, остаётся неприятное понимание того, насколько естественным и собственным казалось это чужое желание.</p>","Cerulean Scourge":"<p data-cpel-flavor=\"substance-1\">Кобальтовый срыв выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — молочно-белый с холодным серым отливом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества слабый металлический запах с аптечной горечью, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Эффект ощущается как быстро нарастающее внутреннее давление: пульс становится громким, кожа теплеет, а в повреждённых местах появляется жгучая пульсация. Организм пытается компенсировать потерю крови учащённым дыханием, из-за чего возникает головокружение и узкое поле зрения. При тяжёлом воздействии тело становится обманчиво лёгким, движения теряют силу, а каждое новое усилие отдаётся тупым гулом в висках.</p>","Brimstone Fumes":"<p data-cpel-flavor=\"substance-1\">Горячий смог выглядит как сухой микрокристаллический порошок, который в герметичном стекле выглядит почти невесомым; отдельные частицы цепляются за стенки и образуют тонкий ореол. Основной оттенок — винно-бордовый; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества почти стерильный запах, за которым остаётся горький минеральный шлейф, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Belladonna":"<p data-cpel-flavor=\"substance-1\">Ночная игла выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — угольно-чёрный с масляным фиолетовым бликом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сладковато-химический запах с лёгкой нотой дыма, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Qat":"<p data-cpel-flavor=\"substance-1\">Сухая искра / Dry Spark — сухая прессованная пластинка из бледно-зелёного растительного волокна и синтетического связующего. Она крошится на тонкие игольчатые хлопья, пахнет горькой травой, пылью и мятой, а во вкусе оставляет терпкую сухость. По краям пластинки заметны серебристые кристаллы стимулятора; под неоном они мерцают, из-за чего препарат и получил своё уличное имя.</p><p data-cpel-flavor=\"substance-2\">Через несколько минут действие ощущается прежде всего как сухая ясность: речь ускоряется, мелкие детали цепляют внимание, а усталость отходит на задний план. Одновременно пересыхает рот, пальцы становятся беспокойными, и телу всё труднее полностью расслабиться. Когда пик проходит, собранность распадается на раздражительность и ощущение пустой усталости — организм словно ещё требует темпа, который нервная система уже не способна поддерживать.</p>","Addlebrain":"<p data-cpel-flavor=\"substance-1\">Мёртвый канал выглядит как сухой микрокристаллический порошок, который в герметичном стекле выглядит почти невесомым; отдельные частицы цепляются за стенки и образуют тонкий ореол. Основной оттенок — бледно-зелёный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества почти стерильный запах, за которым остаётся горький минеральный шлейф, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Blaze":"<p data-cpel-flavor=\"substance-1\">Неоновый жар / Neon Heat выглядит как прозрачный оранжево-золотой гель в мягкой капсуле. Внутри геля вспыхивают крошечные флуоресцентные точки, особенно заметные в ультрафиолете. Запах сладковатый, с нотами цитруса и нагретой электроники; вкус сначала фруктовый, затем остро перечный. Капсула быстро становится тёплой в руке, и это ощущение тепла ещё до приёма делает препарат психологически узнаваемым.</p><p data-cpel-flavor=\"substance-2\">После приёма по коже проходит горячая волна, цвета становятся ярче, а собственный голос кажется громче и увереннее. Боль и страх на короткое время отступают за ощущением внутреннего жара; даже прохладный воздух воспринимается как тёплый. По мере спада эффект меняется: появляется жажда, в висках пульсирует давление, а слишком резкие звуки и свет начинают раздражать сильнее обычного.</p>","Petroleum Bravery":"<p data-cpel-flavor=\"substance-1\">Кардиогель «Храбрость» — плотный кардиогель медно-янтарного цвета, в котором плавают мельчайшие светлые хлопья стабилизатора. Гель медленно ползёт по стенкам капсулы и заметно разжижается от тепла пальцев. Запах тяжёлый, минеральный, с оттенком машинного масла и мяты; вкус резко горький, после него во рту остаётся ощущение прохлады. По виду препарат больше напоминает техническую смазку, чем медицинский состав, что и делает его узнаваемым.</p><p data-cpel-flavor=\"substance-2\">Через несколько секунд после приёма сердцебиение становится медленнее и тяжелее, зато каждый удар ощущается удивительно ровным. Дрожь в руках уходит, дыхание углубляется, а паническая реакция организма приглушается до контролируемого напряжения. Эмоции остаются на месте — препарат не делает человека бесстрашным, — но телесные признаки страха перестают захлёстывать сознание, создавая холодное ощущение собранности.</p>","Cytillesh":"<p data-cpel-flavor=\"substance-1\">Пустая память / Blank Memory почти бесцветен: слегка вязкие капли заметны только по радужной кайме на стекле. Запах сладковато-химический, очень слабый, а вкус напоминает разбавленный анестетик — сначала ничего, затем язык немеет и появляется пустая минеральная горечь. Если посмотреть на флакон под углом, жидкость на секунду кажется серо-фиолетовой, после чего снова становится прозрачной.</p><p data-cpel-flavor=\"substance-2\">Эффект начинается тихо: знакомые слова на секунду кажутся чужими, затем недавние события теряют эмоциональную окраску. Человек ещё понимает, где находится, но отдельные детали прошлого будто перестают иметь за что зацепиться. В голове остаётся странное чистое пространство, сопровождаемое лёгким звоном и ощущением ватной дистанции до собственных воспоминаний; позже память возвращается фрагментами и не всегда в правильном порядке.</p>","Medpatch (Elite)":"<p data-cpel-flavor=\"substance-1\">Медпластырь [Элитный] выглядит как тонкая гибкая пластина из матового биополимера с едва заметной сеткой микрорезервуаров. У этой версии сетка плотнее, чем у младших моделей, а клеевой слой холодит кожу уже при соприкосновении. Внутри пластыря просматривается бледно-зелёный гель; от вскрытой защитной мембраны остаётся почти стерильный запах, за которым остаётся горький минеральный шлейф. Это тяжёлая формула с заметно более насыщенным носителем, поэтому сам пластырь ощущается чуть тяжелее и жёстче обычного медицинского расходника.</p><p data-cpel-flavor=\"substance-2\">После фиксации сначала чувствуется холод клеевого слоя, затем под кожей появляется мягкое покалывание и ритмичное тепло вокруг травмированных участков. Боль не исчезает мгновенно, но становится тише и «дальше», дыхание выравнивается, а напряжённые мышцы постепенно отпускают. По мере расходования микрорезервуаров сетка внутри пластыря тускнеет; к концу работы остаётся только равномерное тепло и лёгкая стянутость кожи.</p>","Dreamlink Serum":"<p data-cpel-flavor=\"substance-1\">Нейросыворотка «Связь снов» — блестящий пурпурный сироп с чёрными и зелёными прожилками, которые медленно перестраиваются даже в неподвижной ампуле. Под ярким светом прожилки напоминают тонкие нейронные ветви, а на стекле остаётся короткий фосфоресцирующий след. Сыворотка пахнет озоном, мятой и влажной электроникой; вкус начинается сладко, но быстро уходит в металлическую горечь. Визуально препарат кажется почти «живым», хотя движение создают только взвешенные микрокапсулы.</p><p data-cpel-flavor=\"substance-2\">После приёма память ощущается не как цепочка мыслей, а как набор ярких сенсорных фрагментов: лица всплывают вместе с запахами, фразы — с цветом помещения, а давно забытые ассоциации соединяются неожиданно быстро. При попытке сосредоточиться на сложном вопросе вокруг нужной мысли будто выстраиваются несколько возможных «дорожек» ответа. Если две независимые догадки совпадают, возникает короткое ощущение узнавания — почти физический щелчок, после которого связь кажется очевидной.</p>","Toxic Effluence":"<p data-cpel-flavor=\"substance-1\">Чёрный сток выглядит как вязкий гель с полимерной основой; он медленно растекается по стеклу и после высыхания оставляет полупрозрачную матовую плёнку. Основной оттенок — угольно-чёрный с масляным фиолетовым бликом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества слабый металлический запах с аптечной горечью, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Soothing Tonic (Lesser)":"<p data-cpel-flavor=\"substance-1\">Реген-тоник «Успокоение» [Слабый] представляет собой прозрачный регенеративный тоник, в котором под светом видны тончайшие волокна биогеля. Основа дымчато-серый; при движении флакона волокна складываются в медленные завитки, словно жидкость пытается стянуть сама себя. Вкус мягкий, солоновато-травяной, с коротким металлическим послевкусием, а запах напоминает кисловатый запах электролита и мокрого камня. Эта мягкая по концентрации версия визуально отличается прежде всего плотностью волокон и более яркой реакцией на тепло ладони.</p><p data-cpel-flavor=\"substance-2\">В первые секунды по телу проходит мягкое тепло, особенно заметное вокруг свежих ран и перенапряжённых мышц. Кожа вокруг повреждений слегка зудит, затем чувство натяжения ослабевает, а мелкая дрожь после стресса постепенно уходит. Препарат не создаёт эйфории: его действие ощущается как спокойная физиологическая «сборка» организма, когда пульс выравнивается, дыхание становится глубже, а тело снова начинает слушаться без лишнего напряжения.</p>","Poison Fizz (Moderate)":"<p data-cpel-flavor=\"substance-1\">Антитокс-леденец «Шипучка» [Средний] выполнен в форме плотного шипучего леденца с полупрозрачной оболочкой и зернистой сердцевиной. Оболочка медно-янтарный; внутри видны крошечные пузырьки, будто конфета всё время медленно «кипит». Во рту сначала чувствуется цитрусовая кислота, затем сильная лекарственная горечь и холод; запах — сухой запах озона и горьких трав. Эта высококонцентрированная профессиональная формула: чем выше грейд, тем плотнее сердцевина и тем ярче короткая вспышка цвета при раскусывании.</p><p data-cpel-flavor=\"substance-2\">Пока леденец растворяется, язык покалывает от кислоты и холода, а в горле остаётся слабое ощущение мятной сухости. Через несколько минут тело становится менее чувствительным к характерной токсической слабости: тошнота и дрожь не исчезают полностью, но воспринимаются контролируемее. Если задействуется вторичная капсула, сладкий вкус мгновенно сменяется сильной химической горечью и коротким ощущением жжения в носоглотке.</p>","Eldritch Flare":"<p data-cpel-flavor=\"substance-1\">Нейровсплеск выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — молочно-белый с холодным серым отливом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сухой запах озона и горьких трав, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые секунды дают только странное ощущение температуры: кожа то холодеет, то внезапно кажется слишком тёплой. Затем появляется металлический привкус, лёгкий звон в ушах и чувство, будто движения перестали идеально совпадать с намерением. По мере усиления воздействия организм начинает расходовать силы на компенсацию — дыхание меняется, мышцы напрягаются, внимание сужается. Даже после спада некоторое время остаются слабость и неприятная сенсорная «зернистость» мира.</p>","Honeyscent":"<p data-cpel-flavor=\"substance-1\">Золотая петля выглядит как сухой микрокристаллический порошок, который в герметичном стекле выглядит почти невесомым; отдельные частицы цепляются за стенки и образуют тонкий ореол. Основной оттенок — янтарно-жёлтый; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества кисловатый запах электролита и мокрого камня, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Восприятие начинает ошибаться раньше, чем человек понимает, что отравлен. Тени кажутся глубже, движения на краю зрения — слишком быстрыми, а обычные звуки получают тревожный второй слой. Организм реагирует на эти ложные сигналы вполне реально: учащается дыхание, ладони холодеют, мышцы готовятся к бегству. При тяжёлом воздействии граница между настоящей угрозой и химически созданным образом почти исчезает, оставляя после себя изматывающую настороженность.</p>","Lethargy Poison":"<p data-cpel-flavor=\"substance-1\">Сонный режим выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — жемчужно-серый; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества почти стерильный запах, за которым остаётся горький минеральный шлейф, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Запах быстро перестаёт быть просто запахом и превращается в навязчивую точку внимания. Кажется, что источник находится совсем рядом и почему-то важен, хотя разум не может объяснить почему. Все остальные ощущения отходят на второй план, и даже движение невольно подстраивается под попытку приблизиться к знакомому аромату. Когда эффект ослабевает, остаётся неприятное понимание того, насколько естественным и собственным казалось это чужое желание.</p>","Tatzlwyrm's Gasp":"<p data-cpel-flavor=\"substance-1\">Пустой вдох выглядит как сухой микрокристаллический порошок, который в герметичном стекле выглядит почти невесомым; отдельные частицы цепляются за стенки и образуют тонкий ореол. Основной оттенок — медно-янтарный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сухой запах озона и горьких трав, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые ощущения приходят изнутри: во рту появляется кислая горечь, желудок тяжелеет, а по спине проходит холодный пот. Затем к тошноте добавляются спазмы и ощущение, будто организм пытается избавиться от всего сразу. Движение и резкие запахи делают состояние хуже, поэтому человек инстинктивно старается замереть и дышать мелко. Даже после ослабления действия ещё некоторое время остаются слабость, сухость во рту и неприятная пустота в животе.</p>","Tears of Death":"<p data-cpel-flavor=\"substance-1\">Финальная доза выглядит как вязкий гель с полимерной основой; он медленно растекается по стеклу и после высыхания оставляет полупрозрачную матовую плёнку. Основной оттенок — дымчато-синий; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сухой запах озона и горьких трав, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Воздействие начинается с мелкой дрожи и ощущения неправильного веса конечностей. Пальцы перестают точно дозировать усилие, шаг становится слишком широким или коротким, а простые движения требуют сознательного контроля. По мере усиления эффекта мышцы будто получают команды с задержкой: тело ещё понимает, что нужно сделать, но ответ приходит поздно и рывками. После спада долго остаются покалывание и неприятная слабость, словно после сильного переохлаждения.</p>","Bottled Catharsis (Lesser)":"<p data-cpel-flavor=\"substance-1\">Нейрококтейль «Катарсис» [Слабый] хранится как двухфазный нейрококтейль: прозрачная основа и почти бесцветный, но с ярким неоновым отблеском взвесь не смешиваются полностью, а образуют медленные спирали. При лёгком движении флакона по стеклу пробегают жемчужные полосы, будто жидкость реагирует на ритм пульса. На вкус коктейль одновременно терпкий и сладковатый, после него на нёбе остаётся прохладная горечь; запах — почти стерильный запах, за которым остаётся горький минеральный шлейф. Эта плотная рабочая формула, поэтому рисунок взвеси у неё гуще и держится дольше.</p><p data-cpel-flavor=\"substance-2\">Эффект начинается с неожиданно глубокого вдоха и ощущения, будто из груди сняли слишком тесный ремень. Навязчивые эмоции не исчезают, но перестают занимать всё внимание: страх, злость или эйфория отступают на фон, позволяя снова отделять собственные решения от химически усиленной реакции. Иногда это сопровождается короткой дрожью, слезами или приступом смеха — нервная система сбрасывает накопившееся напряжение прежде, чем возвращается к ровному состоянию.</p>","Nightmare Vapor":"<p data-cpel-flavor=\"substance-1\">Паник-облако выглядит как сухой микрокристаллический порошок, который в герметичном стекле выглядит почти невесомым; отдельные частицы цепляются за стенки и образуют тонкий ореол. Основной оттенок — угольно-чёрный с масляным фиолетовым бликом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества почти стерильный запах, за которым остаётся горький минеральный шлейф, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Восприятие начинает ошибаться раньше, чем человек понимает, что отравлен. Тени кажутся глубже, движения на краю зрения — слишком быстрыми, а обычные звуки получают тревожный второй слой. Организм реагирует на эти ложные сигналы вполне реально: учащается дыхание, ладони холодеют, мышцы готовятся к бегству. При тяжёлом воздействии граница между настоящей угрозой и химически созданным образом почти исчезает, оставляя после себя изматывающую настороженность.</p>","Gorgon's Breath":"<p data-cpel-flavor=\"substance-1\">Бетонная пыль выглядит как сухой микрокристаллический порошок, который в герметичном стекле выглядит почти невесомым; отдельные частицы цепляются за стенки и образуют тонкий ореол. Основной оттенок — медно-янтарный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества запах холодного пластика, мяты и железа, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Yellow Musk Poison":"<p data-cpel-flavor=\"substance-1\">Янтарная приманка выглядит как сухой микрокристаллический порошок, который в герметичном стекле выглядит почти невесомым; отдельные частицы цепляются за стенки и образуют тонкий ореол. Основной оттенок — янтарно-жёлтый; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества кисловатый запах электролита и мокрого камня, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Запах быстро перестаёт быть просто запахом и превращается в навязчивую точку внимания. Кажется, что источник находится совсем рядом и почему-то важен, хотя разум не может объяснить почему. Все остальные ощущения отходят на второй план, и даже движение невольно подстраивается под попытку приблизиться к знакомому аромату. Когда эффект ослабевает, остаётся неприятное понимание того, насколько естественным и собственным казалось это чужое желание.</p>","Greengut":"<p data-cpel-flavor=\"substance-1\">Аварийный сброс / Emergency Purge — мутная изумрудная жидкость в ударопрочной ампуле, по консистенции ближе к густому электролиту, чем к лекарству. Внутри постоянно держится мелкая пена, а на свету заметен жёлтый маслянистый ободок. Запах резкий: кислота, горькие травы и разогретый пластик; даже рядом с закрытой ампулой чувствуется слабая едкая нота. Визуально это один из тех препаратов, которые не пытаются выглядеть безопасными.</p><p data-cpel-flavor=\"substance-2\">Действие грубое и почти мгновенное: желудок и диафрагму сводит резким спазмом, рот наполняется кислой слюной, а дыхание на несколько секунд сбивается. Внутри возникает ощущение аварийного рефлекса, которому невозможно «объяснить», что угрозы нет. После пика остаются дрожь, горький привкус и болезненная пустота в животе, но именно эта резкая физиологическая реакция и составляет назначение препарата.</p>","Clubhead Poison":"<p data-cpel-flavor=\"substance-1\">Разбитый кадр выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — бледно-зелёный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества слабый металлический запах с аптечной горечью, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Воздействие начинается с мелкой дрожи и ощущения неправильного веса конечностей. Пальцы перестают точно дозировать усилие, шаг становится слишком широким или коротким, а простые движения требуют сознательного контроля. По мере усиления эффекта мышцы будто получают команды с задержкой: тело ещё понимает, что нужно сделать, но ответ приходит поздно и рывками. После спада долго остаются покалывание и неприятная слабость, словно после сильного переохлаждения.</p>","Bottled Catharsis (Minor)":"<p data-cpel-flavor=\"substance-1\">Нейрококтейль «Катарсис» [Малый] хранится как двухфазный нейрококтейль: прозрачная основа и почти бесцветный, но с ярким неоновым отблеском взвесь не смешиваются полностью, а образуют медленные спирали. При лёгком движении флакона по стеклу пробегают жемчужные полосы, будто жидкость реагирует на ритм пульса. На вкус коктейль одновременно терпкий и сладковатый, после него на нёбе остаётся прохладная горечь; запах — кисловатый запах электролита и мокрого камня. Эта мягкая по концентрации версия, поэтому рисунок взвеси у неё гуще и держится дольше.</p><p data-cpel-flavor=\"substance-2\">Эффект начинается с неожиданно глубокого вдоха и ощущения, будто из груди сняли слишком тесный ремень. Навязчивые эмоции не исчезают, но перестают занимать всё внимание: страх, злость или эйфория отступают на фон, позволяя снова отделять собственные решения от химически усиленной реакции. Иногда это сопровождается короткой дрожью, слезами или приступом смеха — нервная система сбрасывает накопившееся напряжение прежде, чем возвращается к ровному состоянию.</p>","Bottled Catharsis (Greater)":"<p data-cpel-flavor=\"substance-1\">Нейрококтейль «Катарсис» [Сильный] хранится как двухфазный нейрококтейль: прозрачная основа и почти бесцветный, но с ярким неоновым отблеском взвесь не смешиваются полностью, а образуют медленные спирали. При лёгком движении флакона по стеклу пробегают жемчужные полосы, будто жидкость реагирует на ритм пульса. На вкус коктейль одновременно терпкий и сладковатый, после него на нёбе остаётся прохладная горечь; запах — резкий травяной запах с перечной нотой. Эта высококонцентрированная профессиональная формула, поэтому рисунок взвеси у неё гуще и держится дольше.</p><p data-cpel-flavor=\"substance-2\">Эффект начинается с неожиданно глубокого вдоха и ощущения, будто из груди сняли слишком тесный ремень. Навязчивые эмоции не исчезают, но перестают занимать всё внимание: страх, злость или эйфория отступают на фон, позволяя снова отделять собственные решения от химически усиленной реакции. Иногда это сопровождается короткой дрожью, слезами или приступом смеха — нервная система сбрасывает накопившееся напряжение прежде, чем возвращается к ровному состоянию.</p>","Numbing Tonic (Moderate)":"<p data-cpel-flavor=\"substance-1\">Нейроанальгетик «Онемение» [Средний] — вязкий нейроанальгетический тоник с гладкой, почти сиропной текстурой. Жидкость почти бесцветный, но с ярким неоновым отблеском, медленно собирается на стенках ампулы и при встряхивании даёт тонкое опаловое кольцо. Во вкусе сначала ощущается холодная сладость, затем появляется аптечная горечь и характерное онемение языка; запах — почти стерильный запах, за которым остаётся горький минеральный шлейф. По плотности это высококонцентрированная профессиональная формула, и старшие версии заметно дольше сохраняют ощущение прохлады во рту.</p><p data-cpel-flavor=\"substance-2\">Онемение начинается с губ и языка, затем волной спускается по шее и плечам. Боль не пропадает как выключенный сигнал — скорее становится приглушённой и далёкой, позволяя телу продолжать работу, несмотря на повреждения. На пике движения ощущаются чуть «чужими», потому что обратная связь от мышц приходит слабее обычного; после спада чувствительность возвращается покалыванием, теплом и тяжестью в уставших конечностях.</p>","Clown Monarch":"<p data-cpel-flavor=\"substance-1\">Карусель выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — медно-янтарный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества запах холодного пластика, мяты и железа, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые секунды дают только странное ощущение температуры: кожа то холодеет, то внезапно кажется слишком тёплой. Затем появляется металлический привкус, лёгкий звон в ушах и чувство, будто движения перестали идеально совпадать с намерением. По мере усиления воздействия организм начинает расходовать силы на компенсацию — дыхание меняется, мышцы напрягаются, внимание сужается. Даже после спада некоторое время остаются слабость и неприятная сенсорная «зернистость» мира.</p>","Soothing Tonic (Moderate)":"<p data-cpel-flavor=\"substance-1\">Реген-тоник «Успокоение» [Средний] представляет собой прозрачный регенеративный тоник, в котором под светом видны тончайшие волокна биогеля. Основа дымчато-серый; при движении флакона волокна складываются в медленные завитки, словно жидкость пытается стянуть сама себя. Вкус мягкий, солоновато-травяной, с коротким металлическим послевкусием, а запах напоминает слабый металлический запах с аптечной горечью. Эта плотная рабочая формула визуально отличается прежде всего плотностью волокон и более яркой реакцией на тепло ладони.</p><p data-cpel-flavor=\"substance-2\">В первые секунды по телу проходит мягкое тепло, особенно заметное вокруг свежих ран и перенапряжённых мышц. Кожа вокруг повреждений слегка зудит, затем чувство натяжения ослабевает, а мелкая дрожь после стресса постепенно уходит. Препарат не создаёт эйфории: его действие ощущается как спокойная физиологическая «сборка» организма, когда пульс выравнивается, дыхание становится глубже, а тело снова начинает слушаться без лишнего напряжения.</p>","Numbing Tonic (Major)":"<p data-cpel-flavor=\"substance-1\">Нейроанальгетик «Онемение» [Высший] — вязкий нейроанальгетический тоник с гладкой, почти сиропной текстурой. Жидкость почти бесцветный, но с ярким неоновым отблеском, медленно собирается на стенках ампулы и при встряхивании даёт тонкое опаловое кольцо. Во вкусе сначала ощущается холодная сладость, затем появляется аптечная горечь и характерное онемение языка; запах — резкий травяной запах с перечной нотой. По плотности это тяжёлая формула с заметно более насыщенным носителем, и старшие версии заметно дольше сохраняют ощущение прохлады во рту.</p><p data-cpel-flavor=\"substance-2\">Онемение начинается с губ и языка, затем волной спускается по шее и плечам. Боль не пропадает как выключенный сигнал — скорее становится приглушённой и далёкой, позволяя телу продолжать работу, несмотря на повреждения. На пике движения ощущаются чуть «чужими», потому что обратная связь от мышц приходит слабее обычного; после спада чувствительность возвращается покалыванием, теплом и тяжестью в уставших конечностях.</p>","Mage Bane":"<p data-cpel-flavor=\"substance-1\">Синапс-глушитель выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — насыщенно-синий; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества запах холодного пластика, мяты и железа, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Mythotoxin":"<p data-cpel-flavor=\"substance-1\">Сброс титана выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — прозрачный с опаловым переливом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества почти стерильный запах, за которым остаётся горький минеральный шлейф, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Запах быстро перестаёт быть просто запахом и превращается в навязчивую точку внимания. Кажется, что источник находится совсем рядом и почему-то важен, хотя разум не может объяснить почему. Все остальные ощущения отходят на второй план, и даже движение невольно подстраивается под попытку приблизиться к знакомому аромату. Когда эффект ослабевает, остаётся неприятное понимание того, насколько естественным и собственным казалось это чужое желание.</p>","Wolfsbane":"<p data-cpel-flavor=\"substance-1\">Морф-стоп выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — прозрачный с опаловым переливом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества резкий травяной запах с перечной нотой, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Shiver":"<p data-cpel-flavor=\"substance-1\">Холодный сон / Cold Dream продаётся как бледно-голубая кристаллическая пастилка с матовой поверхностью. Она всегда кажется холоднее окружающего воздуха и оставляет на пальцах сухой меловой след. Запах почти отсутствует, только слабая мята и металл; вкус ледяной, горький, с коротким сладким послевкусием. При ярком свете внутри кристалла заметны тонкие белые трещины, похожие на морозный узор.</p><p data-cpel-flavor=\"substance-2\">Холод приходит изнутри: сначала немеют губы и кончики пальцев, затем окружающий мир будто отдаляется на несколько шагов. Тревога приглушается, линии предметов слегка плывут, движения становятся ленивыми и запаздывающими. На пике кажется, что тело лежит под тяжёлым прохладным одеялом; позже это спокойствие легко переходит в сонливость и неприятную потерю координации.</p>","Pale Fade":"<p data-cpel-flavor=\"substance-1\">Белый пепел выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — молочно-белый с холодным серым отливом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества запах холодного пластика, мяты и железа, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Контакт сопровождается резким жжением, которое быстро сменяется глубоким зудом и ощущением натянутой кожи. Поверхность становится чрезмерно чувствительной: ткань одежды, холодный воздух и даже собственное движение воспринимаются как раздражение. При сильном воздействии боль уходит глубже, превращаясь в тупое горячее давление в тканях. После спада остаётся болезненная чувствительность и ощущение сухости, будто кожа стала слишком тонкой для окружающего мира.</p>","Nightmare Salt":"<p data-cpel-flavor=\"substance-1\">Чёрный сон выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — угольно-чёрный с масляным фиолетовым бликом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сухой запах озона и горьких трав, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Achaekek's Kiss":"<p data-cpel-flavor=\"substance-1\">Красная черта выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — густой тёмно-красный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сладковато-химический запах с лёгкой нотой дыма, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Запах быстро перестаёт быть просто запахом и превращается в навязчивую точку внимания. Кажется, что источник находится совсем рядом и почему-то важен, хотя разум не может объяснить почему. Все остальные ощущения отходят на второй план, и даже движение невольно подстраивается под попытку приблизиться к знакомому аромату. Когда эффект ослабевает, остаётся неприятное понимание того, насколько естественным и собственным казалось это чужое желание.</p>","Medpatch (Tactical)":"<p data-cpel-flavor=\"substance-1\">Медпластырь [Тактический] выглядит как тонкая гибкая пластина из матового биополимера с едва заметной сеткой микрорезервуаров. У этой версии сетка плотнее, чем у младших моделей, а клеевой слой холодит кожу уже при соприкосновении. Внутри пластыря просматривается графитовый с серебристой взвесью гель; от вскрытой защитной мембраны остаётся кисловатый запах электролита и мокрого камня. Это плотная рабочая формула, поэтому сам пластырь ощущается чуть тяжелее и жёстче обычного медицинского расходника.</p><p data-cpel-flavor=\"substance-2\">После фиксации сначала чувствуется холод клеевого слоя, затем под кожей появляется мягкое покалывание и ритмичное тепло вокруг травмированных участков. Боль не исчезает мгновенно, но становится тише и «дальше», дыхание выравнивается, а напряжённые мышцы постепенно отпускают. По мере расходования микрорезервуаров сетка внутри пластыря тускнеет; к концу работы остаётся только равномерное тепло и лёгкая стянутость кожи.</p>","Medpatch (Commercial)":"<p data-cpel-flavor=\"substance-1\">Медпластырь [Серийный] выглядит как тонкая гибкая пластина из матового биополимера с едва заметной сеткой микрорезервуаров. У этой версии сетка плотнее, чем у младших моделей, а клеевой слой холодит кожу уже при соприкосновении. Внутри пластыря просматривается дымчато-серый гель; от вскрытой защитной мембраны остаётся запах холодного пластика, мяты и железа. Это мягкая по концентрации версия, поэтому сам пластырь ощущается чуть тяжелее и жёстче обычного медицинского расходника.</p><p data-cpel-flavor=\"substance-2\">После фиксации сначала чувствуется холод клеевого слоя, затем под кожей появляется мягкое покалывание и ритмичное тепло вокруг травмированных участков. Боль не исчезает мгновенно, но становится тише и «дальше», дыхание выравнивается, а напряжённые мышцы постепенно отпускают. По мере расходования микрорезервуаров сетка внутри пластыря тускнеет; к концу работы остаётся только равномерное тепло и лёгкая стянутость кожи.</p>","Reaper's Shadow":"<p data-cpel-flavor=\"substance-1\">Последний пакет выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — графитовый с серебристой взвесью; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сухой запах озона и горьких трав, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые секунды дают только странное ощущение температуры: кожа то холодеет, то внезапно кажется слишком тёплой. Затем появляется металлический привкус, лёгкий звон в ушах и чувство, будто движения перестали идеально совпадать с намерением. По мере усиления воздействия организм начинает расходовать силы на компенсацию — дыхание меняется, мышцы напрягаются, внимание сужается. Даже после спада некоторое время остаются слабость и неприятная сенсорная «зернистость» мира.</p>","Vyre's Bliss":"<p data-cpel-flavor=\"substance-1\">Бархатный ноль выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — медно-янтарный; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества слабый металлический запах с аптечной горечью, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Воздействие начинается с мелкой дрожи и ощущения неправильного веса конечностей. Пальцы перестают точно дозировать усилие, шаг становится слишком широким или коротким, а простые движения требуют сознательного контроля. По мере усиления эффекта мышцы будто получают команды с задержкой: тело ещё понимает, что нужно сделать, но ответ приходит поздно и рывками. После спада долго остаются покалывание и неприятная слабость, словно после сильного переохлаждения.</p>","Spider Mold":"<p data-cpel-flavor=\"substance-1\">Тихая сеть выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — жемчужно-серый; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сухой запах озона и горьких трав, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые признаки почти незаметны: внимание начинает проскальзывать мимо привычных деталей, короткие фразы приходится повторять про себя, а недавние события теряют чёткие границы. Затем появляется ощущение «пустых мест» между мыслями — человек знает, что только что что-то делал или говорил, но не сразу понимает что именно. При сильном воздействии речь становится обрывочной, решения замедляются, а собственные воспоминания ощущаются ненадёжными и чужими.</p>","Hemlock":"<p data-cpel-flavor=\"substance-1\">Тихий пульс выглядит как густая жидкость с мелким кристаллическим осадком; после встряхивания осадок превращается в равномерную дымчатую взвесь. Основной оттенок — прозрачный с опаловым переливом; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества слабый металлический запах с аптечной горечью, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Воздействие начинается с мелкой дрожи и ощущения неправильного веса конечностей. Пальцы перестают точно дозировать усилие, шаг становится слишком широким или коротким, а простые движения требуют сознательного контроля. По мере усиления эффекта мышцы будто получают команды с задержкой: тело ещё понимает, что нужно сделать, но ответ приходит поздно и рывками. После спада долго остаются покалывание и неприятная слабость, словно после сильного переохлаждения.</p>","Numbing Tonic (Lesser)":"<p data-cpel-flavor=\"substance-1\">Нейроанальгетик «Онемение» [Слабый] — вязкий нейроанальгетический тоник с гладкой, почти сиропной текстурой. Жидкость почти бесцветный, но с ярким неоновым отблеском, медленно собирается на стенках ампулы и при встряхивании даёт тонкое опаловое кольцо. Во вкусе сначала ощущается холодная сладость, затем появляется аптечная горечь и характерное онемение языка; запах — запах холодного пластика, мяты и железа. По плотности это плотная рабочая формула, и старшие версии заметно дольше сохраняют ощущение прохлады во рту.</p><p data-cpel-flavor=\"substance-2\">Онемение начинается с губ и языка, затем волной спускается по шее и плечам. Боль не пропадает как выключенный сигнал — скорее становится приглушённой и далёкой, позволяя телу продолжать работу, несмотря на повреждения. На пике движения ощущаются чуть «чужими», потому что обратная связь от мышц приходит слабее обычного; после спада чувствительность возвращается покалыванием, теплом и тяжестью в уставших конечностях.</p>","Medpatch (Superior)":"<p data-cpel-flavor=\"substance-1\">Медпластырь [Превосходный] выглядит как тонкая гибкая пластина из матового биополимера с едва заметной сеткой микрорезервуаров. У этой версии сетка плотнее, чем у младших моделей, а клеевой слой холодит кожу уже при соприкосновении. Внутри пластыря просматривается прозрачный с опаловым переливом гель; от вскрытой защитной мембраны остаётся запах холодного пластика, мяты и железа. Это тяжёлая формула с заметно более насыщенным носителем, поэтому сам пластырь ощущается чуть тяжелее и жёстче обычного медицинского расходника.</p><p data-cpel-flavor=\"substance-2\">После фиксации сначала чувствуется холод клеевого слоя, затем под кожей появляется мягкое покалывание и ритмичное тепло вокруг травмированных участков. Боль не исчезает мгновенно, но становится тише и «дальше», дыхание выравнивается, а напряжённые мышцы постепенно отпускают. По мере расходования микрорезервуаров сетка внутри пластыря тускнеет; к концу работы остаётся только равномерное тепло и лёгкая стянутость кожи.</p>","Leadenleg":"<p data-cpel-flavor=\"substance-1\">Якорь выглядит как маслянистая суспензия с очень мелкой взвесью; она держится плотной каплей и тянется короткой нитью, прежде чем снова собраться вместе. Основной оттенок — дымчато-синий; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества слабый металлический запах с аптечной горечью, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Воздействие начинается с мелкой дрожи и ощущения неправильного веса конечностей. Пальцы перестают точно дозировать усилие, шаг становится слишком широким или коротким, а простые движения требуют сознательного контроля. По мере усиления эффекта мышцы будто получают команды с задержкой: тело ещё понимает, что нужно сделать, но ответ приходит поздно и рывками. После спада долго остаются покалывание и неприятная слабость, словно после сильного переохлаждения.</p>","Elixir of Rejuvenation":"<p data-cpel-flavor=\"substance-1\">Реанимационный нанококтейль «Возрождение» похож на лабораторный образец, который случайно оказался среди обычных медикаментов: густая молочно-белая суспензия наполнена чёрными наночешуйками и тонкими радужными нитями. Они не оседают и медленно собираются вокруг стенок флакона, будто реагируют на тепло живой руки. Запах стерильный, с резкой нотой озона и железа; вкус тяжёлый, минеральный, а после глотка язык на несколько секунд кажется совершенно холодным.</p><p data-cpel-flavor=\"substance-2\">Первые секунды ощущаются пугающе: тело резко холодеет, звук приглушается, а сердце будто пропускает удар. Затем приходит мощная волна тепла, за которой мышцы начинают сокращаться ровнее, дыхание углубляется, а боль перестраивается из острой в тупую и быстро отступающую. Сознание возвращается рывками — запахи, свет, давление одежды — словно организм по очереди включает свои системы и заново проверяет, что они способны работать.</p>","Dragon Bile":"<p data-cpel-flavor=\"substance-1\">Внутренний пожар выглядит как вязкий гель с полимерной основой; он медленно растекается по стеклу и после высыхания оставляет полупрозрачную матовую плёнку. Основной оттенок — жемчужно-серый; при косом свете он становится глубже и подчёркивает мелкие включения носителя. У вещества сухой запах озона и горьких трав, а вблизи запах быстро сменяется сухой аптечной горечью. Название хорошо совпадает с внешностью состава: даже в неподвижной ёмкости он выглядит неприятно активным, будто внутри продолжается медленная реакция.</p><p data-cpel-flavor=\"substance-2\">Первые ощущения приходят изнутри: во рту появляется кислая горечь, желудок тяжелеет, а по спине проходит холодный пот. Затем к тошноте добавляются спазмы и ощущение, будто организм пытается избавиться от всего сразу. Движение и резкие запахи делают состояние хуже, поэтому человек инстинктивно старается замереть и дышать мелко. Даже после ослабления действия ещё некоторое время остаются слабость, сухость во рту и неприятная пустота в животе.</p>"};

function replaceFlavor(text, html) {
  if (!text || !html) return text;
  let cleaned = text.replace(/<p data-cpel-flavor="(?:expanded|substance-[12])">[\s\S]*?<\/p>/g, "");
  const hr = cleaned.indexOf("<hr>");
  const start = hr >= 0 ? hr + 4 : 0;
  const tail = cleaned.slice(start);
  const match = tail.match(/<p>[\s\S]*?<\/p>/);
  if (!match) return cleaned + html;
  const pos = start + match.index + match[0].length;
  return cleaned.slice(0, pos) + html + cleaned.slice(pos);
}

function updateFor(item) {
  const src = item?._source ?? item?.toObject?.(false);
  const conv = src?.flags?.[MODULE_ID]?.substanceConversion;
  if (conv?.version !== "1.5.44" || !FLAVOR[conv.source_name]) return null;
  const oldText = src.system?.description?.value ?? "";
  const newText = replaceFlavor(oldText, FLAVOR[conv.source_name]);
  if (newText === oldText) return null;
  return { "system.description.value": newText, [`flags.${MODULE_ID}.version`]: "1.5.51" };
}

Hooks.once("ready", async () => {
  if (!game.user?.isGM) return;
  let updated = 0;
  for (const actor of game.actors ?? []) {
    for (const item of actor.items ?? []) {
      const patch = updateFor(item); if (!patch) continue;
      try { await item.update(patch, {render:false}); updated++; }
      catch (error) { console.warn(`[${MODULE_ID}] v1.5.51: не удалось обновить флейвор «${item.name}»`, error); }
    }
  }
  for (const item of game.items ?? []) {
    const patch = updateFor(item); if (!patch) continue;
    try { await item.update(patch, {render:false}); updated++; }
    catch (error) { console.warn(`[${MODULE_ID}] v1.5.51: не удалось обновить мировой предмет «${item.name}»`, error); }
  }
  if (updated) console.info(`[${MODULE_ID}] v1.5.51: обновлено расширенных описаний: ${updated}`);
});
